class Solution {
public:
    int maxResult(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> dp(n, 0);
        dp[0] = nums[0];
        deque<int> dq;
        dq.push_back(0);
        for (int i = 1; i < n; ++i) {
            while (!dq.empty() && dq.front() < i - k) {
                dq.pop_front();
            }
            dp[i] = nums[i] + dp[dq.front()];
            while (!dq.empty() && dp[dq.back()] <= dp[i]) {
                dq.pop_back();
            }
            dq.push_back(i);
        }
        return dp.back();
    }
};

class Solution {
    public int maxResult(int[] nums, int k) {
        int n = nums.length;
        int[] dp = new int[n];
        dp[0] = nums[0];
        Deque<Integer> dq = new ArrayDeque<>();
        dq.offerLast(0);
        for (int i = 1; i < n; ++i) {
            while (!dq.isEmpty() && dq.peekFirst() < i - k) {
                dq.pollFirst();
            }
            dp[i] = nums[i] + dp[dq.peekFirst()];
            while (!dq.isEmpty() && dp[dq.peekLast()] <= dp[i]) {
                dq.pollLast();
            }
            dq.offerLast(i);
        }
        return dp[n - 1];
    }
}

var maxResult = function(nums, k) {
    const n = nums.length;
    const dp = new Int32Array(n);
    dp[0] = nums[0];
    const dq = [0];
    let head = 0;
    for (let i = 1; i < n; ++i) {
        while (head < dq.length && dq[head] < i - k) {
            head++;
        }
        dp[i] = nums[i] + dp[dq[head]];
        while (dq.length > head && dp[dq[dq.length - 1]] <= dp[i]) {
            dq.pop();
        }
        dq.push(i);
    }
    return dp[n - 1];
};
